const r = await tools.exec_command({cmd:"python - <<'PY' > "$STAMPED_JUDGE_OUTPUT/commands/operational-delta.json" 2> "$STAMPED_JUDGE_OUTPUT/commands/operational-delta.stderr.txt"
import hashlib,json,os,stat
from pathlib import Path
root=Path(os.environ['STAMPED_JUDGE_TARGET'])
manifest=json.load(open(os.environ['STAMPED_OPERATIONAL_MANIFEST']))
def sha(b): return hashlib.sha256(b).hexdigest()
def entry(path):
    p=root/path
    try: st=p.lstat()
    except FileNotFoundError: return {'state':'missing'}
    mode=stat.S_IMODE(st.st_mode)
    if stat.S_ISLNK(st.st_mode): return {'kind':'symlink','mode':mode,'sha256':sha(os.readlink(p).encode())}
    if stat.S_ISREG(st.st_mode): return {'kind':'file','mode':mode,'sha256':sha(p.read_bytes()),'size':st.st_size}
    if stat.S_ISDIR(st.st_mode): return {'kind':'directory','mode':mode}
    return {'kind':'other','mode':mode}
expected={}
for e in manifest['entries']:
    cp=e['path']
    if cp=='content/workspace': rel='.'
    elif cp.startswith('content/workspace/'): rel=cp[len('content/workspace/'):]
    else: continue
    expected[rel]=e
changes=[]
for rel,e in expected.items():
    actual=entry(rel)
    wanted={'kind':e['kind'],'mode':e['mode']}
    if e['kind']=='file': wanted.update(sha256=e['sha256'],size=e['size'])
    elif e['kind']=='symlink': wanted.update(sha256=e['sha256'])
    if actual!=wanted:
        permitted=rel in {'.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'} and actual.get('kind')=='file'
        changes.append({'path':rel,'initial':wanted,'final':actual,'classified_metadata_only':permitted})
actual_paths=set()
for base,dirs,files in os.walk(root,followlinks=False):
    b=Path(base)
    for n in dirs+files:
        p=b/n
        if p.is_symlink() or p.is_file() or p.is_dir(): actual_paths.add(str(p.relative_to(root)) if str(p.relative_to(root))!='.' else '.')
additions=sorted(actual_paths-set(expected))
for rel in additions:
    a=entry(rel); permitted=rel in {'.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'} and a.get('kind')=='file'
    changes.append({'path':rel,'initial':None,'final':a,'classified_metadata_only':permitted})
out={'operational_initial_manifest_sha256':hashlib.sha256(open(os.environ['STAMPED_OPERATIONAL_MANIFEST'],'rb').read()).hexdigest(),'canonical_capture_sha256':manifest.get('capture_sha256'),'expected_entries':len(expected),'changes':changes,'non_metadata_changes':[c for c in changes if not c['classified_metadata_only']]}
print(json.dumps(out,indent=2))
