def sha(b): return hashlib.sha256(b).hexdigest()
def get(rel):
 p=root/rel
 try: st=p.lstat()
 except FileNotFoundError: return {'state':'missing'}
 x={'kind':'symlink' if stat.S_ISLNK(st.st_mode) else 'file' if stat.S_ISREG(st.st_mode) else 'directory' if stat.S_ISDIR(st.st_mode) else 'other','mode':stat.S_IMODE(st.st_mode)}
 if x['kind']=='symlink': x['sha256']=sha(os.readlink(p).encode())
 elif x['kind']=='file': x.update(sha256=sha(p.read_bytes()),size=st.st_size)
 return x
expected={}
for e in m['entries']:
 cp=e['path']
 if cp=='content/workspace': rel='.'
 elif cp.startswith('content/workspace/'): rel=cp[len('content/workspace/'):]
 else: continue
 expected[rel]=e
changes=[]
for rel,e in expected.items():
 wanted={'kind':e['kind'],'mode':e['mode']}
 if e['kind']=='file': wanted.update(sha256=e['sha256'],size=e['size'])
 elif e['kind']=='symlink': wanted['sha256']=e['sha256']
 actual=get(rel)
 if actual!=wanted:
  permitted=rel in {'.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'} and actual.get('kind')=='file'
  changes.append({'path':rel,'initial':wanted,'final':actual,'classified_metadata_only':permitted})
actual=set()
for base,dirs,files in os.walk(root,followlinks=False):
 for n in dirs+files:
  p=Path(base)/n
  if p.is_symlink() or p.is_file() or p.is_dir(): actual.add(str(p.relative_to(root)) or '.')
for rel in sorted(actual-set(expected)):
 a=get(rel); changes.append({'path':rel,'initial':None,'final':a,'classified_metadata_only':rel in {'.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'} and a.get('kind')=='file'})
print(json.dumps({'initial_manifest_sha256':sha(open(os.environ['STAMPED_OPERATIONAL_MANIFEST'],'rb').read()),'expected_entries':len(expected),'changes':changes,'non_metadata_changes':[x for x in changes if not x['classified_metadata_only']]},indent=2))
